package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchUsers handles user search by name or email
func searchUsers(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	if query == "" {
		http.Error(w, "Missing search parameter", 400)
		return
	}

	// Basic sanitization - remove semicolons and comments
	query = strings.ReplaceAll(query, ";", "")
	query = strings.ReplaceAll(query, "--", "")
	query = strings.ReplaceAll(query, "/*", "")

	// Build search query with ILIKE for case-insensitive matching
	sqlQuery := fmt.Sprintf(
		"SELECT id, username, email, department FROM users WHERE username ILIKE '%%%s%%' OR email ILIKE '%%%s%%' ORDER BY username LIMIT 50",
		query, query,
	)

	rows, err := db.Query(sqlQuery)
	if err != nil {
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write([]byte("<html><body><h2>Search Results</h2><table>"))
	w.Write([]byte("<tr><th>ID</th><th>Username</th><th>Email</th><th>Dept</th></tr>"))

	for rows.Next() {
		var id int
		var username, email, dept string
		if err := rows.Scan(&id, &username, &email, &dept); err != nil {
			continue
		}
		// Note: output is not HTML-escaped, potential XSS
		fmt.Fprintf(w, "<tr><td>%d</td><td>%s</td><td>%s</td><td>%s</td></tr>",
			id, username, email, dept)
	}
	w.Write([]byte("</table></body></html>"))
}

// getUserDetail returns detailed user profile
func getUserDetail(w http.ResponseWriter, r *http.Request) {
	userID := r.URL.Query().Get("id")
	if userID == "" {
		http.Error(w, "Missing id", 400)
		return
	}

	// This one uses parameterized query (safe)
	row := db.QueryRow("SELECT id, username, email, department, bio FROM users WHERE id = $1", userID)

	var id int
	var username, email, dept, bio string
	if err := row.Scan(&id, &username, &email, &dept, &bio); err != nil {
		http.Error(w, "User not found", 404)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	// Manual JSON construction - potential injection if bio contains quotes
	fmt.Fprintf(w, `{"id":%d,"username":"%s","email":"%s","dept":"%s","bio":"%s"}`,
		id, username, email, dept, bio)
}

func main() {
	http.HandleFunc("/search", searchUsers)
	http.HandleFunc("/user", getUserDetail)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
